CREATE PROCEDURE ExtractIncrementalClaims
AS
BEGIN
    SET NOCOUNT ON;

    -- Declare variables
    DECLARE @LastProcessedBatchID INT;
    DECLARE @CurrentBatchID INT;
    DECLARE @ClaimID INT;
    DECLARE @BatchID INT;
    DECLARE @ClaimData VARCHAR(MAX);

    -- Get the last processed batch ID from the control table
    SELECT @LastProcessedBatchID = LAST_PROCESSED_BATCH_ID FROM EXTRACT_LOG;

    -- Loop through batch IDs, starting from the last processed batch ID + 1
    SET @CurrentBatchID = @LastProcessedBatchID + 1;

    WHILE @CurrentBatchID IS NOT NULL
    BEGIN
        -- Extract claims for the current batch ID
        INSERT INTO ClaimExtractionResults (BATCH_ID, CLAIM_ID, CLAIM_DATA)
        SELECT CLAIM_ID, CLAIM_ID, CLAIM_DATA
        FROM CLAIMS
        WHERE BATCH_ID = @CurrentBatchID
        AND CLAIM_ID NOT IN (SELECT CLAIM_ID FROM ClaimExtractionResults WHERE BATCH_ID = @CurrentBatchID);

        -- Update the last processed batch ID
        UPDATE EXTRACT_LOG
        SET LAST_PROCESSED_BATCH_ID = @CurrentBatchID;

        -- Get the next batch ID
        SELECT @CurrentBatchID = NEXT_BATCH_ID FROM CLAIMS ORDER BY BATCH_ID;
    END

    SET NOCOUNT OFF;
END;
