-- Metadata Repository Schema Design

CREATE TABLE MetadataRepository (
    MetadataID INT PRIMARY KEY,
    TableName VARCHAR(255) NOT NULL,
    SourceSystem VARCHAR(255),
    TableType VARCHAR(50) CHECK (TableType IN ('Fact', 'Dimension')),
    LastUpdated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE TransformationRule (
    RuleID INT PRIMARY KEY,
    MetadataID INT,
    TransformationType VARCHAR(50) CHECK (TransformationType IN ('CurrencyConversion', 'DateStandardization', 'NullHandling', 'Other')),
    RuleDescription TEXT,
    SourceDataType VARCHAR(50),
    TargetDataType VARCHAR(50),
    TransformationLogic TEXT,
    FOREIGN KEY (MetadataID) REFERENCES MetadataRepository(MetadataID)
);

CREATE TABLE TableMetadata (
    MetadataID INT PRIMARY KEY,
    TableName VARCHAR(255) NOT NULL,
    SourceSystem VARCHAR(255),
    TableType VARCHAR(50) CHECK (TableType IN ('Fact', 'Dimension')),
    ColumnName VARCHAR(255) NOT NULL,
    ColumnDataType VARCHAR(50),
    Description TEXT,
    FOREIGN KEY (TableName) REFERENCES MetadataRepository(TableName)
);

CREATE TABLE Lineage (
    LineageID INT PRIMARY KEY,
    SourceColumn VARCHAR(255) NOT NULL,
    TargetColumn VARCHAR(255) NOT NULL,
    TransformationRuleID INT,
    FOREIGN KEY (TransformationRuleID) REFERENCES TransformationRule(RuleID)
);


