-- Lineage Report Query (Example: Dependency of TransactionAmount in TRANSACTIONS)

SELECT
    t.TableName,
    tm.ColumnName AS TargetColumn,
    tr.TransformationType,
    tr.RuleDescription,
    lm.SourceDataType,
    lm.TargetDataType
FROM
    Lineage l
JOIN
    TransformationRule tr ON l.TransformationRuleID = tr.RuleID
JOIN
    TableMetadata tm ON l.TargetColumn = tm.ColumnName AND l.TableName = tm.TableName
JOIN
    MetadataRepository lm ON tm.TableName = lm.TableName AND tm.ColumnName = lm.ColumnName
WHERE
    l.SourceColumn = 'TransactionAmount'
ORDER BY
    l.LineageID;
